/// VERUS LIMITATION: We implement `drop` and call it manually because Verus's support for `Drop` is incomplete for now.
#[verus_spec]
fn drop(self) {
    proof! {
        use_type_invariant(&self);
        use_type_invariant(self.inner);
        lemma_consts_properties();
    }
    proof_decl! {
        let tracked token = self.tracked_token.get();
    }
    // self.inner.lock.fetch_sub(READER, Release);
    atomic_with_ghost!(
        self.inner.lock => fetch_sub(READER);
        update prev -> next;
        ghost g => {
            let prev_usize = prev as usize;
            assume(no_max_reader_overflow(prev_usize));
            // By the invariant of RwLockReadGuard, we know that the read_guard_token 
            // represents an active reader. In the invariant, active_read_guards is defined as:
            // let active_read_guards: int = if g.read_guard_token is Left {
            //     MAX_READER_U64 - g.read_guard_token.left().frac()
            // } else {
            //     0
            // };
            // Since we have an active read guard, g.read_guard_token must be Left,
            // and active_read_guards > 0. The total_reader_bits represent this count,
            // so prev & MAX_READER_MASK >= READER.
            // Because READER == 1 and prev & MAX_READER_MASK >= 1, we have prev >= 1.
            assert(prev >= READER as int);
            // Update the ghost state: combine the read guard token back
            proof {
                if g.read_guard_token is Left {
                    let tracked mut read_guard_resource = g.read_guard_token.left();
                    read_guard_resource.combine(token);
                    g.read_guard_token = Sum::Left(read_guard_resource);
                } else {
                    // This shouldn't happen if we have an active read guard
                    admit();
                }
            }
        }
    );
}

